-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다
-- (줄 수·개인/애매 줄 수·표 권한·정책·칸 권한 해시 변화 없음).
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261025190000' and name='call_personal')=1 then '예' else '아니오' end as value
union all select 'source and shape checks accept the three call values, class check present',case when (select count(*) from pg_constraint where conrelid=to_regclass('public.app_feed_items') and conname in('app_feed_items_source_check','app_feed_items_shape_check','app_feed_items_call_class_check'))=3 and pg_get_constraintdef((select oid from pg_constraint where conrelid=to_regclass('public.app_feed_items') and conname='app_feed_items_source_check')) like '%call_personal%' and pg_get_constraintdef((select oid from pg_constraint where conrelid=to_regclass('public.app_feed_items') and conname='app_feed_items_call_class_check')) like '%pinned_at IS NULL%' then '예' else '아니오' end
union all select 'new columns present, no default',case when (select count(*) from pg_attribute a where a.attrelid=to_regclass('public.app_feed_items') and not a.attisdropped and a.attname in('moved_at','refilled_at') and not a.attnotnull and not a.atthasdef)=2 then '예' else '아니오' end
union all select 'partial unique index on call source_ref',case when exists(select 1 from pg_index i where i.indexrelid=to_regclass('public.app_feed_items_call_ref_key') and i.indisunique and i.indrelid=to_regclass('public.app_feed_items') and i.indpred is not null) then '예' else '아니오' end
union all select 'guard invoker, empty search_path, no private call, call-only moves',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_feed_item_guard()') and not prosecdef and proconfig=array['search_path=""'] and prosrc not like '%private.%' and prosrc like '%FEED_LINK_SCOPE%' and prosrc like '%FEED_RAW_TEXT_CLEAR_ONLY%' and prosrc like '%FEED_SOURCE_CALL_ONLY%') then '예' else '아니오' end
union all select 'guard execute revoked from everyone',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_feed_item_guard()') and coalesce(proacl::text,'')!~'(^|[{,])(anon|authenticated|service_role)?=') then '예' else '아니오' end
union all select 'one guard trigger',case when (select count(*) from pg_trigger where tgrelid=to_regclass('public.app_feed_items') and not tgisinternal and tgname='app_feed_items_guard')=1 then '예' else '아니오' end
union all select 'two new functions: definer, empty search_path, execute only authenticated',case when (select count(*) from pg_proc p where p.oid in(to_regprocedure('public.app_feed_call_move(uuid,text)'),to_regprocedure('public.app_feed_call_work_info(uuid,text,text,uuid)')) and p.prosecdef and p.proconfig=array['search_path=""'] and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=')=2 then '예' else '아니오' end
union all select 'authenticated still cannot insert delete or write source title moved_at refilled_at',case when not has_table_privilege('authenticated','public.app_feed_items','insert') and not has_table_privilege('authenticated','public.app_feed_items','delete') and not has_column_privilege('authenticated','public.app_feed_items','source','update') and not has_column_privilege('authenticated','public.app_feed_items','title','update') and not has_column_privilege('authenticated','public.app_feed_items','counterpart','update') and not has_column_privilege('authenticated','public.app_feed_items','moved_at','update') and not has_column_privilege('authenticated','public.app_feed_items','refilled_at','update') then '예' else '아니오' end
union all select 'service_role cannot write the new columns or update rows',case when not has_column_privilege('service_role','public.app_feed_items','moved_at','insert') and not has_column_privilege('service_role','public.app_feed_items','refilled_at','insert') and not has_any_column_privilege('service_role','public.app_feed_items','update') and not has_table_privilege('service_role','public.app_feed_items','delete') then '예' else '아니오' end
union all select 'no anon or PUBLIC table privilege, RLS on, one policy',case when exists(select 1 from pg_class where oid=to_regclass('public.app_feed_items') and relrowsecurity and relacl::text!~'(^|[{,])(anon)?=') and (select count(*) from pg_policy where polrelid=to_regclass('public.app_feed_items'))=1 then '예' else '아니오' end
union all select 'feed items rows',(select count(*)::text from public.app_feed_items)
union all select 'feed items personal or unsure rows',(select count(*)::text from public.app_feed_items where source in('call_personal','call_unsure'))
union all select 'feed table grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'))),'')
  ||coalesce((select string_agg(a.attname::text||':'||a.attacl::text,',' order by a.attname) from pg_attribute a where a.attrelid=to_regclass('public.app_feed_items') and a.attnum>0 and not a.attisdropped and a.attacl is not null),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'))),''));
